                        P("rn_den", "QBiPoly", True,
                          "r_n DENOMINATOR — a NONZERO bivariate-q QBiPoly"),
                        P("rk_num", "QBiPoly", True,
                          "r_k NUMERATOR — F(n,k+1)/F(n,k) numerator QBiPoly"),
